import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});

describe('list_sessions frame validation', () => {
  it('accepts a bare list_sessions frame with no optional fields', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
  });

  it('accepts list_sessions with a valid integer limit and a valid before cursor', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    expect(validateMessage({type: 'list_sessions', limit: 10, before})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it('strips unknown fields such as userId', () => {
    const result = validateMessage({type: 'list_sessions', userId: 'other'});
    expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
  });

  it.each([
    ['string limit', {type: 'list_sessions', limit: 'ten'}],
    ['negative limit', {type: 'list_sessions', limit: -1}],
    ['fractional limit', {type: 'list_sessions', limit: 1.5}],
  ])('rejects a malformed limit: %s', (_label, frame) => {
    const result = validateMessage(frame);
    expect(result.valid).toBe(false);
    expect((result as {valid: false; error: string}).error).toMatch(/limit/i);
  });

  it.each([
    ['non-object before', {type: 'list_sessions', before: 'not-an-object'}],
    ['empty sessionId', {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}],
    [
      'sessionId too long',
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
    ],
    ['unparseable updatedAt', {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}],
    ['boolean updatedAt', {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}],
  ])('rejects a malformed before cursor: %s', (_label, frame) => {
    const result = validateMessage(frame);
    expect(result.valid).toBe(false);
    expect((result as {valid: false; error: string}).error).toMatch(/before/i);
  });
});

